// JavaScript has no built-in ISO week function; this is the standard
// ISO 8601 algorithm (Thursday of the week decides the week-year).
function isoWeekInfo(y, m, day) {
  const d = new Date(Date.UTC(y, m, day));
  const dayNum = (d.getUTCDay() + 6) % 7; // Monday=0..Sunday=6
  d.setUTCDate(d.getUTCDate() - dayNum + 3); // Thursday of this week
  const isoYear = d.getUTCFullYear();
  const jan4 = new Date(Date.UTC(isoYear, 0, 4));
  const week = 1 + Math.round(((d - jan4) / 86400000 - 3 + ((jan4.getUTCDay() + 6) % 7)) / 7);
  return { isoYear, week };
}
console.log('calendar year:', 2024, '| ISO:', isoWeekInfo(2024, 11, 30));
